<script setup>
import { computed } from 'vue'
import { online, percent, rate, displayPing } from '../utils/format'
import MiniChart from './MiniChart.vue'
const props = defineProps({ server: { type: Object, required: true }, showCharts: Boolean, showThreeNet: Boolean, networkNames: { type: Object, default: () => ({}) } })
const live = computed(() => online(props.server)); const ping = (key) => props.server.ping?.[key] ?? props.server[`${key}_ping`]; const loss = (key) => props.server.loss?.[key] ?? props.server[`${key}_loss`]; const cpu = computed(() => props.server.cpu ?? props.server.cpu_usage); const memory = computed(() => props.server.ram_percent ?? props.server.memory_percent ?? props.server.memory)
</script>
<template><article class="server-card" :class="{ offline: !live }"><div class="card-head"><div><div class="server-name">{{ server.name || server.hostname || `Server ${server.id}` }}</div><div class="server-meta">{{ server.os_name || server.os || 'Unknown OS' }} <span>·</span> {{ server.location || server.ip_v4 || '—' }}</div></div><span class="status-pill" :class="live ? 'online' : 'offline'">{{ live ? 'Online' : 'Offline' }}</span></div><div class="metric-grid"><div><span>CPU</span><strong>{{ percent(cpu) }}</strong></div><div><span>Memory</span><strong>{{ percent(memory) }}</strong></div><div><span>Uptime</span><strong>{{ server.uptime_human || server.uptime || '—' }}</strong></div><div><span>Traffic</span><strong>{{ rate(server.net_out ?? server.network_out) }}</strong></div></div><div v-if="showCharts && showThreeNet && (server.ping || server.loss)" class="net-charts"><div v-for="key in ['ct','cu','cm','bgp']" :key="key" class="net-chart"><div><span>{{ networkNames[key] || key.toUpperCase() }}</span><b>{{ displayPing(ping(key)) || percent(loss(key)) }}</b></div><MiniChart :values="server.ping?.[key] || server.loss?.[key] || []" :color="key === 'ct' ? '#8b5cf6' : key === 'cu' ? '#14b8a6' : key === 'cm' ? '#f59e0b' : '#ef4444'" /></div></div><a class="details-link" :href="`#/server/${encodeURIComponent(server.id)}`">View details <span>→</span></a></article></template>
